// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271, ECDSA, SignatureChecker} from "../src/PuttyV2.sol";

contract InvMutTest is Test, IERC1271 {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        vm.warp(1_000_000);
    }

    // IERC1271 wallet: c's SignatureChecker staticcalls us (order.maker = address(this))
    // and accepts any signature, so fillOrder can be driven without a real ECDSA key.
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }

    // Empty-succeeding fallback token: satisfies baseAsset.code.length > 0 and makes the
    // premium/strike safeTransferFrom low-level calls succeed (empty returndata is accepted).
    fallback() external payable {}

    function testFuzz_property(
        bool isCall,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        strike = bound(strike, 0, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        duration = bound(duration, 1, 10_000 days - 1); // nonzero so the buggy write is observable
        expiration = bound(expiration, 1_000_001, 2_000_000); // order not expired at warp time
        address baseAsset = address(new FallbackToken());

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory emptySig = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, emptySig, floorAssetTokenIds);

        // Rule: after filling a LONG order, the TAKER's position (the opposite-order id)
        // must remain unexpired: positionExpirations[uint256(hashOppositeOrder(order))] == 0.
        // The reference writes the expiration under uint256(hashOrder(order)) (long side);
        // the mutant always writes it under the taker's positionId, making it nonzero.
        bytes32 takerPositionId = c.hashOppositeOrder(order);
        assertTrue(c.positionExpirations(uint256(takerPositionId)) == 0);
    }
}

contract FallbackToken {
    fallback() external payable {}
    receive() external payable {}
}
